/**
 * Marx's Capital, Expert: written questions added with the fourth level
 * (QUIZ_VERSION 5), on the finer points of the text and later readings.
 * Positions in a debate are stated as their authors' views.
 */
import type { L3, LinuxQuestion as Q } from "../linux/types";

const q = (id: string, question: L3, a: L3, w: [L3, L3, L3], e: L3): Q => ({ id, since: 5, q: question, a, w, e });

const commodity: Q[] = [
  q("mx-com-x01", ["What is the defect of the 'expanded form' of value, according to Marx?", "Quel est le défaut de la « forme développée » de la valeur, selon Marx ?", "¿Cuál es el defecto de la «forma desplegada» del valor, según Marx?"], ["It is never complete: the series of equivalents is endless and differs for each commodity, so there is no single expression of value", "Elle n'est jamais achevée : la série des équivalents est sans fin et diffère pour chaque marchandise, il n'y a donc pas d'expression unique de la valeur", "Nunca está completa: la serie de equivalentes no tiene fin y difiere para cada mercancía, así que no hay una expresión única del valor"], [["It allows only two commodities", "Elle n'admet que deux marchandises", "Solo admite dos mercancías"], ["It already contains money", "Elle contient déjà la monnaie", "Ya contiene el dinero"], ["It measures value in labour hours directly", "Elle mesure la valeur directement en heures de travail", "Mide el valor directamente en horas de trabajo"]], ["Reversing the expanded form gives the general form, where all commodities express their value in one; that is the step towards money (Volume I, chapter 1, section 3).", "Inverser la forme développée donne la forme générale, où toutes les marchandises expriment leur valeur dans une seule : c'est le pas vers la monnaie (Livre I, chapitre 1, section 3).", "Invertir la forma desplegada da la forma general, en la que todas las mercancías expresan su valor en una: es el paso hacia el dinero (Libro I, capítulo 1, sección 3)."]),
  q("mx-com-x02", ["Why, for Marx, does the discovery that value is labour not dispel commodity fetishism?", "Pourquoi, pour Marx, la découverte que la valeur est du travail ne dissipe-t-elle pas le fétichisme ?", "¿Por qué, para Marx, el descubrimiento de que el valor es trabajo no disipa el fetichismo?"], ["Because producers still relate to each other through the exchange of their products: the appearance comes from practice, not from a lack of knowledge", "Parce que les producteurs restent liés entre eux par l'échange de leurs produits : l'apparence vient de la pratique, pas d'un manque de savoir", "Porque los productores siguen relacionándose a través del intercambio de sus productos: la apariencia viene de la práctica, no de una falta de conocimiento"], [["Because the discovery was false", "Parce que la découverte était fausse", "Porque el descubrimiento era falso"], ["Because workers are never told about it", "Parce qu'on ne le dit jamais aux ouvriers", "Porque nunca se lo dicen a los obreros"], ["Because fetishism is a religious belief", "Parce que le fétichisme est une croyance religieuse", "Porque el fetichismo es una creencia religiosa"]], ["Marx credits the classical economists with the discovery, but it 'by no means dissipates the mist': as long as social labour is organised through private exchange, its relations take the form of relations between things.", "Marx attribue la découverte aux économistes classiques, mais elle « ne dissipe nullement le brouillard » : tant que le travail social s'organise par l'échange privé, ses rapports prennent la forme de rapports entre des choses.", "Marx atribuye el descubrimiento a los economistas clásicos, pero «no disipa en modo alguno la niebla»: mientras el trabajo social se organice por el intercambio privado, sus relaciones toman la forma de relaciones entre cosas."]),
  q("mx-com-x03", ["Why does Capital begin with the commodity rather than with labour or with capital?", "Pourquoi Le Capital commence-t-il par la marchandise plutôt que par le travail ou le capital ?", "¿Por qué El capital empieza por la mercancía y no por el trabajo o el capital?"], ["It is the 'cell-form' of capitalist wealth: the exposition goes from its simplest, most abstract form to more concrete ones", "C'est la « forme cellulaire » de la richesse capitaliste : l'exposé va de sa forme la plus simple et la plus abstraite vers des formes plus concrètes", "Es la «forma celular» de la riqueza capitalista: la exposición va de su forma más simple y abstracta a formas más concretas"], [["Because commodities came first in history", "Parce que les marchandises sont apparues les premières dans l'histoire", "Porque las mercancías aparecieron primero en la historia"], ["Because Ricardo began his Principles that way", "Parce que Ricardo commençait ainsi ses Principes", "Porque Ricardo empezaba así sus Principios"], ["Because labour cannot be defined", "Parce que le travail ne peut pas être défini", "Porque el trabajo no puede definirse"]], ["The 1867 preface calls the value-form of the product 'the economic cell-form'. The order of exposition is not a historical narrative; whether it follows a Hegelian method is itself debated.", "La préface de 1867 appelle la forme-valeur du produit « la forme cellulaire économique ». L'ordre de l'exposé n'est pas un récit historique ; qu'il suive une méthode hégélienne est lui-même discuté.", "El prólogo de 1867 llama a la forma de valor del producto «la forma celular económica». El orden de la exposición no es un relato histórico; si sigue un método hegeliano es en sí objeto de debate."]),
];

const money: Q[] = [
  q("mx-mon-x01", ["Why can paper tokens circulate in place of gold, according to Marx?", "Pourquoi des signes en papier peuvent-ils circuler à la place de l'or, selon Marx ?", "¿Por qué pueden circular signos de papel en lugar del oro, según Marx?"], ["As means of circulation, money exists only fleetingly between sale and purchase, so a symbol made valid by the state can stand in for it", "Comme moyen de circulation, la monnaie n'existe qu'un instant entre la vente et l'achat : un symbole rendu valable par l'État peut la remplacer", "Como medio de circulación, el dinero solo existe un instante entre la venta y la compra, así que un símbolo validado por el Estado puede sustituirlo"], [["Because paper has its own value", "Parce que le papier a sa propre valeur", "Porque el papel tiene valor propio"], ["Because prices are set by the quantity of paper", "Parce que les prix sont fixés par la quantité de papier", "Porque los precios los fija la cantidad de papel"], ["Because gold has no value once coined", "Parce que l'or n'a plus de valeur une fois frappé", "Porque el oro pierde su valor una vez acuñado"]], ["In chapter 3, paper money represents gold within the limits of the gold that would otherwise circulate; issued beyond them, it represents less gold and prices in paper rise.", "Au chapitre 3, le papier-monnaie représente l'or dans les limites de l'or qui circulerait autrement ; émis au-delà, il représente moins d'or et les prix en papier montent.", "En el capítulo 3, el papel moneda representa oro dentro de los límites del oro que circularía en otro caso; emitido más allá, representa menos oro y los precios en papel suben."]),
  q("mx-mon-x02", ["What does Marx hold against the quantity theory of Hume and Ricardo?", "Que reproche Marx à la théorie quantitative de Hume et Ricardo ?", "¿Qué reprocha Marx a la teoría cuantitativa de Hume y Ricardo?"], ["It assumes commodities enter circulation without a price and money without a value; for Marx prices come first and hoards adjust the quantity of money", "Elle suppose que les marchandises entrent en circulation sans prix et la monnaie sans valeur ; pour Marx les prix viennent d'abord et les trésors ajustent la quantité de monnaie", "Supone que las mercancías entran en la circulación sin precio y el dinero sin valor; para Marx los precios van primero y los tesoros ajustan la cantidad de dinero"], [["It ignores the velocity of money", "Elle ignore la vitesse de la monnaie", "Ignora la velocidad del dinero"], ["It applies only to paper money", "Elle ne vaut que pour le papier-monnaie", "Solo vale para el papel moneda"], ["It makes prices fall when money increases", "Elle fait baisser les prix quand la monnaie augmente", "Hace bajar los precios cuando aumenta el dinero"]], ["Hoards act as channels that absorb or release metal money, so the amount in circulation follows prices. Marx grants the quantity theory a role for inconvertible paper.", "Les trésors servent de canaux qui absorbent ou libèrent la monnaie métallique : la quantité en circulation suit les prix. Marx accorde un rôle à la théorie quantitative pour le papier inconvertible.", "Los tesoros sirven de canales que absorben o liberan el dinero metálico, así que la cantidad en circulación sigue a los precios. Marx concede un papel a la teoría cuantitativa para el papel inconvertible."]),
  q("mx-mon-x03", ["Today's currencies are not convertible into gold. How do readers of Marx treat this?", "Les monnaies actuelles ne sont pas convertibles en or. Comment les lecteurs de Marx traitent-ils cette question ?", "Las monedas actuales no son convertibles en oro. ¿Cómo tratan esto los lectores de Marx?"], ["Some argue the general-equivalent role can be held by state-backed credit money; how well a non-commodity money fits his theory is debated", "Certains soutiennent que le rôle d'équivalent général peut être tenu par une monnaie de crédit garantie par l'État ; dans quelle mesure une monnaie non marchandise s'accorde avec sa théorie est discuté", "Algunos sostienen que el papel de equivalente general puede cumplirlo un dinero de crédito respaldado por el Estado; hasta qué punto un dinero no mercancía encaja con su teoría se discute"], [["Marx described today's money exactly", "Marx a décrit exactement la monnaie actuelle", "Marx describió exactamente el dinero actual"], ["They agree his theory of value fell with the gold standard", "Ils s'accordent à dire que sa théorie de la valeur est tombée avec l'étalon-or", "Coinciden en que su teoría del valor cayó con el patrón oro"], ["They hold that money no longer matters in capitalism", "Ils tiennent que la monnaie ne compte plus dans le capitalisme", "Sostienen que el dinero ya no importa en el capitalismo"]], ["Writers such as de Brunhoff, Lapavitsas and Heinrich take different positions on whether a money commodity is needed; the question is open.", "Des auteurs comme de Brunhoff, Lapavitsas ou Heinrich prennent des positions différentes sur la nécessité d'une marchandise monnaie ; la question est ouverte.", "Autores como de Brunhoff, Lapavitsas o Heinrich toman posiciones distintas sobre la necesidad de una mercancía dinero; la cuestión está abierta."]),
];

const surplus: Q[] = [
  q("mx-sv-x01", ["What did Marx find wrong with Senior's 'last hour' argument against the Ten Hours' Bill?", "Qu'est-ce que Marx trouvait faux dans l'argument de « la dernière heure » de Senior contre la loi des dix heures ?", "¿Qué encontraba Marx erróneo en el argumento de «la última hora» de Senior contra la ley de las diez horas?"], ["Senior took the shares of the product's value for periods of the working day, as if profit were made only in the last hour", "Senior prenait les parts de la valeur du produit pour des périodes de la journée de travail, comme si le profit ne se faisait qu'à la dernière heure", "Senior tomaba las partes del valor del producto por periodos de la jornada, como si la ganancia se hiciera solo en la última hora"], [["Senior forgot the cost of machinery", "Senior oubliait le coût des machines", "Senior olvidaba el coste de las máquinas"], ["Senior counted wages twice", "Senior comptait deux fois les salaires", "Senior contaba dos veces los salarios"], ["Senior assumed a ten-hour day already", "Senior supposait déjà une journée de dix heures", "Senior ya suponía una jornada de diez horas"]], ["Every hour transfers old value and creates new value; shortening the day lowers surplus value only by the surplus part of the lost hour (Volume I, chapter 9, section 3).", "Chaque heure transmet de la valeur ancienne et crée de la valeur nouvelle ; raccourcir la journée ne réduit la plus-value que de la part de surtravail de l'heure perdue (Livre I, chapitre 9, section 3).", "Cada hora transfiere valor antiguo y crea valor nuevo; acortar la jornada solo reduce el plusvalor en la parte de plustrabajo de la hora perdida (Libro I, capítulo 9, sección 3)."]),
  q("mx-sv-x02", ["How does the same hour of spinning both preserve old value and add new value?", "Comment la même heure de filage conserve-t-elle la valeur ancienne et ajoute-t-elle de la valeur nouvelle ?", "¿Cómo conserva la misma hora de hilado el valor antiguo y añade valor nuevo?"], ["As concrete useful labour it transfers the value of cotton and spindles to the yarn; as abstract labour it adds new value", "Comme travail concret utile, il transmet au fil la valeur du coton et des broches ; comme travail abstrait, il ajoute de la valeur nouvelle", "Como trabajo concreto útil transfiere al hilo el valor del algodón y los husos; como trabajo abstracto añade valor nuevo"], [["It does one in the morning and the other in the afternoon", "Il fait l'un le matin et l'autre l'après-midi", "Hace una cosa por la mañana y otra por la tarde"], ["The machine adds value and the worker preserves it", "La machine ajoute de la valeur et l'ouvrier la conserve", "La máquina añade valor y el obrero lo conserva"], ["It does not: old value is lost in production", "Ce n'est pas le cas : la valeur ancienne se perd dans la production", "No es así: el valor antiguo se pierde en la producción"]], ["Chapter 8 draws on the twofold character of labour: a rise in productivity changes how much old value is transferred per hour, not how much new value an hour adds.", "Le chapitre 8 s'appuie sur le double caractère du travail : une hausse de productivité change la valeur ancienne transmise par heure, pas la valeur nouvelle qu'ajoute une heure.", "El capítulo 8 se apoya en el doble carácter del trabajo: un aumento de productividad cambia cuánto valor antiguo se transfiere por hora, no cuánto valor nuevo añade una hora."]),
  q("mx-sv-x03", ["Which labour is 'productive' in Marx's sense under capitalism?", "Quel travail est « productif » au sens de Marx sous le capitalisme ?", "¿Qué trabajo es «productivo» en el sentido de Marx bajo el capitalismo?"], ["Labour that produces surplus value for capital: a teacher employed by a school-owner is productive, a self-employed tailor is not", "Le travail qui produit de la plus-value pour un capital : un enseignant employé par un patron d'école est productif, un tailleur indépendant ne l'est pas", "El trabajo que produce plusvalor para un capital: un maestro empleado por el dueño de una escuela es productivo, un sastre por cuenta propia no"], [["Only labour that makes material goods", "Seulement le travail qui fabrique des biens matériels", "Solo el trabajo que fabrica bienes materiales"], ["Any useful labour", "Tout travail utile", "Todo trabajo útil"], ["Any labour paid a wage", "Tout travail payé par un salaire", "Todo trabajo pagado con un salario"]], ["The schoolmaster example is in chapter 16. A domestic servant paid out of revenue is a wage-earner but not productive in this sense; the distinction concerns the social form, not the usefulness.", "L'exemple du maître d'école est au chapitre 16. Un domestique payé sur le revenu est salarié mais pas productif en ce sens ; la distinction porte sur la forme sociale, pas sur l'utilité.", "El ejemplo del maestro está en el capítulo 16. Un criado pagado con la renta es asalariado pero no productivo en este sentido; la distinción se refiere a la forma social, no a la utilidad."]),
];

const workingDay: Q[] = [
  q("mx-wd-x01", ["Why do limits on the working day push capital towards relative surplus value?", "Pourquoi les limites de la journée de travail poussent-elles le capital vers la plus-value relative ?", "¿Por qué los límites de la jornada empujan al capital hacia el plusvalor relativo?"], ["With the length fixed, more surplus can come only from cutting necessary labour or intensifying work, which drives machinery and productivity", "La durée étant fixée, plus de surtravail ne peut venir que d'une baisse du travail nécessaire ou d'une intensification, ce qui pousse au machinisme et à la productivité", "Fijada la duración, más plustrabajo solo puede venir de reducir el trabajo necesario o intensificar el trabajo, lo que impulsa la maquinaria y la productividad"], [["Because wages are fixed by law too", "Parce que les salaires sont aussi fixés par la loi", "Porque los salarios también los fija la ley"], ["Because absolute surplus value is forbidden", "Parce que la plus-value absolue est interdite", "Porque el plusvalor absoluto está prohibido"], ["They do not: they stop surplus value altogether", "Elles ne le font pas : elles arrêtent toute plus-value", "No lo hacen: detienen todo plusvalor"]], ["Marx follows the Factory Acts into chapter 15: the shorter day came with faster machines and closer supervision, a 'condensation' of labour.", "Marx suit les lois sur les fabriques jusqu'au chapitre 15 : la journée plus courte s'est accompagnée de machines plus rapides et d'une surveillance plus serrée, une « condensation » du travail.", "Marx sigue las leyes fabriles hasta el capítulo 15: la jornada más corta llegó con máquinas más rápidas y una vigilancia más estrecha, una «condensación» del trabajo."]),
  q("mx-wd-x02", ["What does Marx mean by calling capital 'dead labour that, vampire-like, lives only by sucking living labour'?", "Que veut dire Marx en appelant le capital « travail mort qui, semblable au vampire, ne s'anime qu'en suçant le travail vivant » ?", "¿Qué quiere decir Marx al llamar al capital «trabajo muerto que, como un vampiro, solo vive chupando trabajo vivo»?"], ["Past labour embodied in means of production grows only by absorbing new labour, so capital drives to extend the working day without limit", "Le travail passé incorporé dans les moyens de production ne croît qu'en absorbant du travail nouveau : le capital pousse à allonger la journée sans limite", "El trabajo pasado incorporado en los medios de producción solo crece absorbiendo trabajo nuevo, así que el capital empuja a alargar la jornada sin límite"], [["That machines are dangerous to workers", "Que les machines sont dangereuses pour les ouvriers", "Que las máquinas son peligrosas para los obreros"], ["That capitalists are cruel people", "Que les capitalistes sont des gens cruels", "Que los capitalistas son gente cruel"], ["That capital consumes itself over time", "Que le capital se consume avec le temps", "Que el capital se consume con el tiempo"]], ["The image (chapter 10) concerns a social relation, not individual morals: the same chapter says the capitalist only personifies capital and the conditions are set by competition.", "L'image (chapitre 10) porte sur un rapport social, pas sur la morale des individus : le même chapitre dit que le capitaliste ne fait que personnifier le capital et que la concurrence impose les conditions.", "La imagen (capítulo 10) se refiere a una relación social, no a la moral individual: el mismo capítulo dice que el capitalista solo personifica al capital y que la competencia impone las condiciones."]),
  q("mx-wd-x03", ["A fall in the number of workers can be made up by a higher rate of surplus value. What limits this, according to Marx?", "Une baisse du nombre d'ouvriers peut être compensée par un taux de plus-value plus élevé. Qu'est-ce qui le limite, selon Marx ?", "Una baja del número de obreros puede compensarse con una tasa de plusvalor más alta. ¿Qué lo limita, según Marx?"], ["The day itself: one worker cannot give more than 24 hours minus necessary labour, so two 12-hour workers cannot be replaced by one", "La journée elle-même : un ouvrier ne peut fournir plus de 24 heures moins le travail nécessaire, donc deux ouvriers de 12 heures ne peuvent être remplacés par un seul", "La propia jornada: un obrero no puede dar más de 24 horas menos el trabajo necesario, así que dos obreros de 12 horas no pueden sustituirse por uno"], [["The law on minimum wages", "La loi sur le salaire minimum", "La ley del salario mínimo"], ["The amount of constant capital", "Le montant du capital constant", "El monto del capital constante"], ["Nothing: the rate can rise without limit", "Rien : le taux peut monter sans limite", "Nada: la tasa puede subir sin límite"]], ["Chapter 11's second law of the mass of surplus value. It foreshadows the falling rate of profit: replacing workers with machines narrows the base from which surplus value is drawn.", "C'est la deuxième loi de la masse de plus-value, au chapitre 11. Elle annonce la baisse du taux de profit : remplacer des ouvriers par des machines réduit la base d'où vient la plus-value.", "Es la segunda ley de la masa de plusvalor, en el capítulo 11. Anuncia la caída de la tasa de ganancia: sustituir obreros por máquinas estrecha la base de la que sale el plusvalor."]),
];

const relative: Q[] = [
  q("mx-rel-x01", ["Why does machinery at first lengthen the working day, though it saves labour?", "Pourquoi le machinisme allonge-t-il d'abord la journée de travail, alors qu'il économise du travail ?", "¿Por qué la maquinaria alarga primero la jornada, aunque ahorra trabajo?"], ["The machine risks 'moral depreciation' when cheaper models appear, and its owner gains extra surplus value while it is new: both push to use it as long as possible", "La machine risque une « usure morale » quand des modèles moins chers apparaissent, et son propriétaire gagne une plus-value extra tant qu'elle est nouvelle : tout pousse à l'utiliser le plus longtemps possible", "La máquina corre el riesgo de un «desgaste moral» cuando aparecen modelos más baratos, y su dueño gana un plusvalor extraordinario mientras es nueva: todo empuja a usarla lo más posible"], [["Because machines must warm up", "Parce que les machines doivent chauffer", "Porque las máquinas deben calentarse"], ["Because workers ask for longer hours", "Parce que les ouvriers demandent des journées plus longues", "Porque los obreros piden jornadas más largas"], ["Because the law required it", "Parce que la loi l'exigeait", "Porque la ley lo exigía"]], ["Chapter 15, section 3: idle machinery loses value without transferring it, so night shifts and relays follow. The limits set by the Factory Acts then turn the drive towards intensity.", "Chapitre 15, section 3 : une machine à l'arrêt perd de la valeur sans la transmettre, d'où le travail de nuit et les relais. Les limites des lois sur les fabriques tournent ensuite cette pression vers l'intensité.", "Capítulo 15, sección 3: una máquina parada pierde valor sin transferirlo, de ahí el trabajo nocturno y los relevos. Los límites de las leyes fabriles orientan después esa presión hacia la intensidad."]),
  q("mx-rel-x02", ["How can machinery raise the rate of surplus value yet put pressure on the rate of profit?", "Comment le machinisme peut-il élever le taux de plus-value tout en pesant sur le taux de profit ?", "¿Cómo puede la maquinaria elevar la tasa de plusvalor y a la vez presionar la tasa de ganancia?"], ["It cheapens wage goods and intensifies work, raising $s'$, but replaces living labour, the source of new value, raising $c/v$", "Il rend les biens salariaux moins chers et intensifie le travail, ce qui élève $s'$, mais remplace le travail vivant, source de valeur nouvelle, ce qui élève $c/v$", "Abarata los bienes salariales e intensifica el trabajo, lo que eleva $s'$, pero sustituye trabajo vivo, fuente de valor nuevo, lo que eleva $c/v$"], [["It lowers both", "Il les abaisse tous les deux", "Las baja a las dos"], ["It creates value itself, so profit rises", "Il crée lui-même de la valeur, donc le profit monte", "Crea valor por sí misma, así que la ganancia sube"], ["It has no effect on either", "Il n'a d'effet sur aucun des deux", "No afecta a ninguna"]], ["The tension between the two effects is worked out in Volume III, chapters 13 to 15; a higher $s'$ is the first counteracting influence.", "La tension entre les deux effets est développée au Livre III, chapitres 13 à 15 ; un $s'$ plus élevé est la première des causes qui contrarient la baisse.", "La tensión entre ambos efectos se desarrolla en el Libro III, capítulos 13 a 15; un $s'$ más alto es la primera de las causas contrarrestantes."]),
  q("mx-rel-x03", ["Why is real subsumption called the 'specifically capitalist mode of production'?", "Pourquoi la subsomption réelle est-elle appelée « mode de production spécifiquement capitaliste » ?", "¿Por qué la subsunción real se llama «modo de producción específicamente capitalista»?"], ["Because the labour process itself is reshaped by capital, through cooperation, machinery and science, instead of being taken over as it was", "Parce que le procès de travail lui-même est refaçonné par le capital, par la coopération, le machinisme et la science, au lieu d'être repris tel quel", "Porque el propio proceso de trabajo lo transforma el capital, mediante la cooperación, la maquinaria y la ciencia, en vez de tomarlo tal cual"], [["Because workers own the machines", "Parce que les ouvriers possèdent les machines", "Porque los obreros poseen las máquinas"], ["Because it existed before capitalism", "Parce qu'elle existait avant le capitalisme", "Porque existía antes del capitalismo"], ["Because wages are paid in money", "Parce que les salaires sont payés en argent", "Porque los salarios se pagan en dinero"]], ["Under formal subsumption a craftsman's way of working stays and only the day lengthens; under real subsumption the worker depends on capital's organisation of production. The 'Results of the Immediate Process of Production' develops the pair.", "Sous la subsomption formelle, la façon de travailler de l'artisan reste et seule la journée s'allonge ; sous la subsomption réelle, l'ouvrier dépend de l'organisation de la production par le capital. Les « Résultats du procès de production immédiat » développent le couple.", "Con la subsunción formal se mantiene la forma de trabajar del artesano y solo se alarga la jornada; con la real, el obrero depende de la organización de la producción por el capital. Los «Resultados del proceso inmediato de producción» desarrollan el par."]),
];

const wages: Q[] = [
  q("mx-wag-x01", ["Why does Marx call 'the value of labour' an imaginary expression, like 'the value of the earth'?", "Pourquoi Marx dit-il que « la valeur du travail » est une expression imaginaire, comme « la valeur de la terre » ?", "¿Por qué Marx llama a «el valor del trabajo» una expresión imaginaria, como «el valor de la tierra»?"], ["Labour is the substance and measure of value and has no value itself; what is sold and has a value is labour-power", "Le travail est la substance et la mesure de la valeur et n'a pas de valeur lui-même ; ce qui se vend et a une valeur, c'est la force de travail", "El trabajo es la sustancia y la medida del valor y no tiene valor propio; lo que se vende y tiene valor es la fuerza de trabajo"], [["Because labour is free", "Parce que le travail est gratuit", "Porque el trabajo es gratuito"], ["Because wages are always paid in kind", "Parce que les salaires sont toujours payés en nature", "Porque los salarios siempre se pagan en especie"], ["Because the earth produces value", "Parce que la terre produit de la valeur", "Porque la tierra produce valor"]], ["Chapter 19: the 'value of labour' would be the value of a twelve-hour day measured in twelve hours, a tautology. The wage form makes the price of labour-power appear as the price of labour.", "Chapitre 19 : la « valeur du travail » serait la valeur d'une journée de douze heures mesurée en douze heures, une tautologie. La forme salaire fait apparaître le prix de la force de travail comme prix du travail.", "Capítulo 19: el «valor del trabajo» sería el valor de una jornada de doce horas medido en doce horas, una tautología. La forma salario hace aparecer el precio de la fuerza de trabajo como precio del trabajo."]),
  q("mx-wag-x02", ["The daily wage rises from 60 for 10 hours to 66 for 12 hours. What happens to the price of an hour of labour?", "Le salaire journalier passe de 60 pour 10 heures à 66 pour 12 heures. Qu'arrive-t-il au prix d'une heure de travail ?", "El salario diario pasa de 60 por 10 horas a 66 por 12 horas. ¿Qué le ocurre al precio de una hora de trabajo?"], ["It falls, from 6 to 5.5", "Il baisse, de 6 à 5,5", "Baja, de 6 a 5,5"], [["It rises, from 6 to 6.6", "Il monte, de 6 à 6,6", "Sube, de 6 a 6,6"], ["It stays at 6", "Il reste à 6", "Se queda en 6"], ["It rises, from 6 to 6.5", "Il monte, de 6 à 6,5", "Sube, de 6 a 6,5"]], ["Chapter 20: a higher daily wage can hide a lower price of labour when the day lengthens more than the pay; the extra hours also wear out the worker faster.", "Chapitre 20 : un salaire journalier plus élevé peut cacher un prix du travail plus bas quand la journée s'allonge plus que la paie ; les heures en plus usent aussi l'ouvrier plus vite.", "Capítulo 20: un salario diario más alto puede ocultar un precio del trabajo más bajo cuando la jornada se alarga más que la paga; las horas de más también desgastan antes al obrero."]),
  q("mx-wag-x03", ["Why do piece wages, for Marx, encourage subcontracting and 'sweating'?", "Pourquoi le salaire aux pièces favorise-t-il, pour Marx, la sous-traitance et le « sweating » ?", "¿Por qué el salario a destajo favorece, para Marx, la subcontratación y el «sweating»?"], ["Because output is measured by the piece, middlemen can take work at one price and pay workers less, living off the difference", "Comme le produit se mesure à la pièce, des intermédiaires peuvent prendre le travail à un prix et payer moins les ouvriers, en vivant de la différence", "Como el producto se mide por pieza, unos intermediarios pueden tomar el trabajo a un precio y pagar menos a los obreros, viviendo de la diferencia"], [["Because piece wages are higher than time wages", "Parce que le salaire aux pièces est plus élevé que le salaire au temps", "Porque el salario a destajo es más alto que el salario por tiempo"], ["Because the law requires middlemen", "Parce que la loi impose des intermédiaires", "Porque la ley exige intermediarios"], ["Because workers cannot count pieces", "Parce que les ouvriers ne savent pas compter les pièces", "Porque los obreros no saben contar las piezas"]], ["Chapter 21: the product controls the quality and intensity of labour, so supervision can be handed to intermediaries; the same logic runs through later home-working and platform work, an extension debated by readers today.", "Chapitre 21 : le produit contrôle la qualité et l'intensité du travail, si bien que la surveillance peut être confiée à des intermédiaires ; la même logique traverse le travail à domicile et le travail de plateforme, prolongement discuté aujourd'hui.", "Capítulo 21: el producto controla la calidad y la intensidad del trabajo, así que la vigilancia puede delegarse en intermediarios; la misma lógica atraviesa el trabajo a domicilio y el de plataformas, una extensión que hoy se discute."]),
];

const accumulation: Q[] = [
  q("mx-acc-x01", ["What separates the concentration of capital from its centralisation?", "Qu'est-ce qui distingue la concentration du capital de sa centralisation ?", "¿Qué distingue la concentración del capital de su centralización?"], ["Concentration is growth of single capitals by accumulation; centralisation is the merging of existing capitals, through competition and credit", "La concentration est la croissance de capitaux individuels par l'accumulation ; la centralisation est la fusion de capitaux existants, par la concurrence et le crédit", "La concentración es el crecimiento de capitales individuales por acumulación; la centralización es la fusión de capitales existentes, mediante la competencia y el crédito"], [["They are two names for the same process", "Ce sont deux noms du même processus", "Son dos nombres del mismo proceso"], ["Centralisation is done by the state", "La centralisation est faite par l'État", "La centralización la hace el Estado"], ["Concentration lowers the composition of capital", "La concentration abaisse la composition du capital", "La concentración baja la composición del capital"]], ["Chapter 25: centralisation can enlarge a capital at once, as joint-stock companies and railways show, without new accumulation; 'one capitalist always kills many' (chapter 32).", "Chapitre 25 : la centralisation peut agrandir un capital d'un coup, comme le montrent les sociétés par actions et les chemins de fer, sans accumulation nouvelle ; « un capitaliste en tue toujours beaucoup d'autres » (chapitre 32).", "Capítulo 25: la centralización puede agrandar un capital de golpe, como muestran las sociedades por acciones y los ferrocarriles, sin nueva acumulación; «un capitalista mata a muchos otros» (capítulo 32)."]),
  q("mx-acc-x02", ["Why, for Marx, can wages not rise enough to stop accumulation for good?", "Pourquoi, pour Marx, les salaires ne peuvent-ils pas monter assez pour arrêter durablement l'accumulation ?", "¿Por qué, para Marx, los salarios no pueden subir lo bastante como para detener la acumulación para siempre?"], ["When wages rise, accumulation slows and labour-saving methods spread, enlarging the reserve army until wages fall back", "Quand les salaires montent, l'accumulation ralentit et les méthodes qui économisent du travail se répandent, ce qui grossit l'armée de réserve jusqu'à ce que les salaires baissent", "Cuando los salarios suben, la acumulación se frena y se extienden los métodos que ahorran trabajo, lo que agranda el ejército de reserva hasta que los salarios bajan"], [["Because the law fixes wages", "Parce que la loi fixe les salaires", "Porque la ley fija los salarios"], ["Because population grows faster than capital", "Parce que la population croît plus vite que le capital", "Porque la población crece más que el capital"], ["Because workers spend all they earn", "Parce que les ouvriers dépensent tout ce qu'ils gagnent", "Porque los obreros gastan todo lo que ganan"]], ["'The rate of accumulation is the independent, not the dependent, variable' (chapter 25): Marx reverses the Malthusian link between population and wages.", "« Le taux d'accumulation est la variable indépendante, non la variable dépendante » (chapitre 25) : Marx renverse le lien malthusien entre population et salaires.", "«La tasa de acumulación es la variable independiente, no la dependiente» (capítulo 25): Marx invierte el vínculo malthusiano entre población y salarios."]),
  q("mx-acc-x03", ["Why can the value composition $c/v$ rise more slowly than the technical composition?", "Pourquoi la composition-valeur $c/v$ peut-elle monter moins vite que la composition technique ?", "¿Por qué la composición de valor $c/v$ puede subir más despacio que la composición técnica?"], ["Higher productivity also cheapens the means of production, so their mass per worker grows faster than their value", "Une productivité plus élevée rend aussi les moyens de production moins chers : leur masse par ouvrier croît plus vite que leur valeur", "Una productividad mayor también abarata los medios de producción, así que su masa por obrero crece más rápido que su valor"], [["Because wages fall to zero", "Parce que les salaires tombent à zéro", "Porque los salarios caen a cero"], ["Because machines create value", "Parce que les machines créent de la valeur", "Porque las máquinas crean valor"], ["It cannot: the two always rise together", "C'est impossible : les deux montent toujours ensemble", "No puede: ambas suben siempre juntas"]], ["Marx notes this in chapter 25, and Volume III counts the cheapening of constant capital among the influences that counteract the falling rate of profit.", "Marx le note au chapitre 25, et le Livre III compte la baisse de prix du capital constant parmi les causes qui contrarient la baisse du taux de profit.", "Marx lo señala en el capítulo 25, y el Libro III cuenta el abaratamiento del capital constante entre las causas que contrarrestan la caída de la tasa de ganancia."]),
];

const primitive: Q[] = [
  q("mx-pri-x01", ["What role does Marx give the public debt in primitive accumulation?", "Quel rôle Marx donne-t-il à la dette publique dans l'accumulation primitive ?", "¿Qué papel da Marx a la deuda pública en la acumulación originaria?"], ["It gives idle money the power to breed, making it capital without risk, and it fosters joint-stock companies, finance and the taxes that ruin small producers", "Elle donne à l'argent oisif le pouvoir de se reproduire, en fait du capital sans risque, et favorise les sociétés par actions, la finance et les impôts qui ruinent les petits producteurs", "Da al dinero ocioso el poder de reproducirse, lo convierte en capital sin riesgo, y fomenta las sociedades por acciones, las finanzas y los impuestos que arruinan a los pequeños productores"], [["It had no role: debt came later", "Aucun : la dette est venue plus tard", "Ninguno: la deuda vino después"], ["It protected peasants from enclosure", "Elle protégeait les paysans des enclosures", "Protegía a los campesinos de los cercamientos"], ["It paid wages to the first workers", "Elle payait les salaires des premiers ouvriers", "Pagaba los salarios de los primeros obreros"]], ["Chapter 31 lists the colonial system, the public debt, modern taxation and protection as levers that 'hasten' the transition, using the power of the state.", "Le chapitre 31 range le système colonial, la dette publique, la fiscalité moderne et le protectionnisme parmi les leviers qui « hâtent » le passage, en usant du pouvoir de l'État.", "El capítulo 31 enumera el sistema colonial, la deuda pública, la fiscalidad moderna y el proteccionismo como palancas que «aceleran» la transición, usando el poder del Estado."]),
  q("mx-pri-x02", ["What did Wakefield's 'systematic colonisation' propose, as Marx reports in chapter 33?", "Que proposait la « colonisation systématique » de Wakefield, selon le chapitre 33 ?", "¿Qué proponía la «colonización sistemática» de Wakefield, según el capítulo 33?"], ["An artificially high price for colonial land, so that settlers had to work for wages for years before buying any, the proceeds bringing in more workers", "Un prix artificiellement élevé de la terre coloniale, pour que les colons travaillent des années comme salariés avant d'en acheter, le produit servant à faire venir d'autres ouvriers", "Un precio artificialmente alto de la tierra colonial, para que los colonos trabajaran años como asalariados antes de comprarla, y con lo recaudado traer más obreros"], [["Free land for every settler", "De la terre gratuite pour chaque colon", "Tierra gratis para cada colono"], ["The abolition of wage labour in the colonies", "L'abolition du salariat dans les colonies", "La abolición del trabajo asalariado en las colonias"], ["Sending capitalists only, without workers", "N'envoyer que des capitalistes, sans ouvriers", "Enviar solo capitalistas, sin obreros"]], ["Marx reads it as an admission: wage labour has to be manufactured by keeping workers from the means of production, which is the secret of primitive accumulation in Europe too.", "Marx y lit un aveu : il faut fabriquer le salariat en tenant les ouvriers à l'écart des moyens de production, ce qui est aussi le secret de l'accumulation primitive en Europe.", "Marx lo lee como una confesión: el trabajo asalariado hay que fabricarlo manteniendo a los obreros lejos de los medios de producción, que es también el secreto de la acumulación originaria en Europa."]),
  q("mx-pri-x03", ["In chapter 32, how does capitalist property relate to private property based on one's own labour?", "Au chapitre 32, quel rapport y a-t-il entre la propriété capitaliste et la propriété privée fondée sur le travail personnel ?", "En el capítulo 32, ¿qué relación hay entre la propiedad capitalista y la propiedad privada basada en el trabajo propio?"], ["It is the first negation of it; its own expropriation, 'the negation of the negation', re-establishes individual property on the basis of cooperation and common possession of land and means of production", "Elle en est la première négation ; sa propre expropriation, « la négation de la négation », rétablit la propriété individuelle sur la base de la coopération et de la possession commune de la terre et des moyens de production", "Es su primera negación; su propia expropiación, «la negación de la negación», restablece la propiedad individual sobre la base de la cooperación y la posesión común de la tierra y los medios de producción"], [["It is the same property under another name", "C'est la même propriété sous un autre nom", "Es la misma propiedad con otro nombre"], ["It grows out of the savings of the self-employed", "Elle naît de l'épargne des travailleurs indépendants", "Nace del ahorro de los trabajadores por cuenta propia"], ["It restores small peasant property", "Elle rétablit la petite propriété paysanne", "Restablece la pequeña propiedad campesina"]], ["The Hegelian phrasing drew Dühring's attack; Engels answered in Anti-Dühring that Marx proves the process historically first. Whether 'individual property' here means personal property is still discussed.", "La formule hégélienne a valu à Marx l'attaque de Dühring ; Engels a répondu dans l'Anti-Dühring que Marx démontre d'abord le processus historiquement. Ce que signifie ici « propriété individuelle » reste discuté.", "La fórmula hegeliana le valió a Marx el ataque de Dühring; Engels respondió en el Anti-Dühring que Marx demuestra primero el proceso históricamente. Qué significa aquí «propiedad individual» sigue discutiéndose."]),
];

const circulation: Q[] = [
  q("mx-cir-x01", ["Why are buying, selling and bookkeeping 'faux frais' of production in Volume II?", "Pourquoi l'achat, la vente et la comptabilité sont-ils des « faux frais » de production au Livre II ?", "¿Por qué la compra, la venta y la contabilidad son «falsos gastos» de producción en el Libro II?"], ["They only change the form of value and add none, so they are paid out of surplus value, however necessary they are", "Ils ne changent que la forme de la valeur et n'en ajoutent pas : ils sont payés sur la plus-value, si nécessaires soient-ils", "Solo cambian la forma del valor y no añaden ninguno, así que se pagan del plusvalor, por necesarios que sean"], [["Because clerks are paid too much", "Parce que les employés sont trop payés", "Porque los empleados cobran demasiado"], ["Because they are useless and could be dropped", "Parce qu'ils sont inutiles et pourraient être supprimés", "Porque son inútiles y podrían suprimirse"], ["Because they create value, but too slowly", "Parce qu'ils créent de la valeur, mais trop lentement", "Porque crean valor, pero demasiado despacio"]], ["Chapter 6: a clerk's labour may be exploited, and necessary for the capitalist, without producing value. Storage and transport needed for use are treated as production.", "Chapitre 6 : le travail d'un employé peut être exploité, et nécessaire au capitaliste, sans produire de valeur. Le stockage et le transport nécessaires à l'usage sont traités comme de la production.", "Capítulo 6: el trabajo de un empleado puede ser explotado, y necesario para el capitalista, sin producir valor. El almacenamiento y el transporte necesarios para el uso se tratan como producción."]),
  q("mx-cir-x02", ["How does Marx link the turnover of fixed capital to the periodic cycle of crises?", "Comment Marx relie-t-il la rotation du capital fixe au cycle périodique des crises ?", "¿Cómo vincula Marx la rotación del capital fijo con el ciclo periódico de las crisis?"], ["Fixed capital is renewed in waves over several years, which gives a material basis for a cycle of about ten years", "Le capital fixe se renouvelle par vagues sur plusieurs années, ce qui donne une base matérielle à un cycle d'une dizaine d'années", "El capital fijo se renueva en oleadas a lo largo de varios años, lo que da una base material a un ciclo de unos diez años"], [["Machines break down all at once", "Les machines tombent en panne toutes en même temps", "Las máquinas se averían todas a la vez"], ["Fixed capital never needs replacing", "Le capital fixe n'a jamais besoin d'être remplacé", "El capital fijo nunca necesita reemplazo"], ["Crises are caused by bad harvests only", "Les crises viennent seulement des mauvaises récoltes", "Las crisis solo vienen de malas cosechas"]], ["Chapter 9 treats it as a material basis of the cycle, not its cause. Later business-cycle theory took up replacement investment in many forms.", "Le chapitre 9 en fait une base matérielle du cycle, non sa cause. La théorie du cycle a ensuite repris l'investissement de remplacement sous bien des formes.", "El capítulo 9 la trata como una base material del ciclo, no su causa. La teoría del ciclo retomó después la inversión de reposición de muchas formas."]),
  q("mx-cir-x03", ["Why is transport productive of value in Volume II, while bookkeeping is not?", "Pourquoi le transport produit-il de la valeur au Livre II, et pas la comptabilité ?", "¿Por qué el transporte produce valor en el Libro II y la contabilidad no?"], ["Transport changes the useful effect of the product, its location, and continues production; bookkeeping only records the movement of value", "Le transport change l'effet utile du produit, son lieu, et prolonge la production ; la comptabilité ne fait qu'enregistrer le mouvement de la valeur", "El transporte cambia el efecto útil del producto, su lugar, y prolonga la producción; la contabilidad solo registra el movimiento del valor"], [["Because transport workers are paid more", "Parce que les transporteurs sont mieux payés", "Porque los transportistas cobran más"], ["Because bookkeeping uses no machines", "Parce que la comptabilité n'utilise pas de machines", "Porque la contabilidad no usa máquinas"], ["They are treated the same way", "Ils sont traités de la même façon", "Se tratan del mismo modo"]], ["Chapter 6 treats the transport industry as a branch of production whose product is a change of place, consumed as it is produced.", "Le chapitre 6 traite l'industrie des transports comme une branche de production dont le produit est un changement de lieu, consommé au moment où il est produit.", "El capítulo 6 trata la industria del transporte como una rama de la producción cuyo producto es un cambio de lugar, consumido a la vez que se produce."]),
];

const reproduction: Q[] = [
  q("mx-rep-x01", ["In simple reproduction, why is the condition $\\text{I}(v+s) = \\text{II}c$ and not $\\text{I}(c+v+s) = \\text{II}c$?", "En reproduction simple, pourquoi la condition est-elle $\\text{I}(v+s) = \\text{II}c$ et non $\\text{I}(c+v+s) = \\text{II}c$ ?", "En la reproducción simple, ¿por qué la condición es $\\text{I}(v+s) = \\text{II}c$ y no $\\text{I}(c+v+s) = \\text{II}c$?"], ["Department I's own constant capital is replaced within department I; only what its workers and capitalists consume must be exchanged with department II", "Le capital constant du secteur I se remplace à l'intérieur du secteur I ; seul ce que consomment ses ouvriers et ses capitalistes s'échange avec le secteur II", "El capital constante del sector I se repone dentro del sector I; solo lo que consumen sus obreros y capitalistas se intercambia con el sector II"], [["Because department I produces no surplus value", "Parce que le secteur I ne produit pas de plus-value", "Porque el sector I no produce plusvalor"], ["Because $\\text{I}c$ is consumed by workers", "Parce que $\\text{I}c$ est consommé par les ouvriers", "Porque $\\text{I}c$ lo consumen los obreros"], ["The two conditions are the same", "Les deux conditions sont identiques", "Las dos condiciones son iguales"]], ["$\\text{I}c$ is a part of the means of production that department I uses itself; $\\text{II}(v+s)$ stays inside department II as consumer goods. The cross exchange is what must balance.", "$\\text{I}c$ est une partie des moyens de production que le secteur I utilise lui-même ; $\\text{II}(v+s)$ reste dans le secteur II sous forme de biens de consommation. C'est l'échange croisé qui doit s'équilibrer.", "$\\text{I}c$ es una parte de los medios de producción que el propio sector I usa; $\\text{II}(v+s)$ queda dentro del sector II como bienes de consumo. Lo que debe equilibrarse es el intercambio cruzado."]),
  q("mx-rep-x02", ["How did Bukharin answer Rosa Luxemburg's claim that expanded reproduction needs non-capitalist buyers?", "Comment Boukharine a-t-il répondu à l'idée de Rosa Luxemburg selon laquelle la reproduction élargie a besoin d'acheteurs non capitalistes ?", "¿Cómo respondió Bujarin a la tesis de Rosa Luxemburg de que la reproducción ampliada necesita compradores no capitalistas?"], ["Accumulation creates its own demand: the extra means of production and the consumption of the extra workers absorb the surplus, if proportions hold", "L'accumulation crée sa propre demande : les moyens de production supplémentaires et la consommation des ouvriers supplémentaires absorbent le surplus, si les proportions tiennent", "La acumulación crea su propia demanda: los medios de producción adicionales y el consumo de los obreros adicionales absorben el excedente, si se mantienen las proporciones"], [["He agreed and called for colonies", "Il était d'accord et prônait des colonies", "Estuvo de acuerdo y abogó por colonias"], ["He denied that surplus value exists", "Il niait l'existence de la plus-value", "Negó la existencia del plusvalor"], ["He said capitalists consume all surplus value", "Il disait que les capitalistes consomment toute la plus-value", "Dijo que los capitalistas consumen todo el plusvalor"]], ["Bukharin's 'Imperialism and the Accumulation of Capital' (1924). The exchange turns on whether the schemes show a possibility or describe a dynamic; Luxemburg's thesis returns in Harvey's accumulation by dispossession.", "« L'impérialisme et l'accumulation du capital » de Boukharine (1924). Le débat porte sur la question de savoir si les schémas montrent une possibilité ou décrivent une dynamique ; la thèse de Luxemburg revient dans l'accumulation par dépossession de Harvey.", "«El imperialismo y la acumulación del capital» de Bujarin (1924). El debate gira sobre si los esquemas muestran una posibilidad o describen una dinámica; la tesis de Luxemburg vuelve en la acumulación por desposesión de Harvey."]),
  q("mx-rep-x03", ["What did Henryk Grossman draw from Otto Bauer's reproduction scheme run over many years?", "Qu'a tiré Henryk Grossmann du schéma de reproduction d'Otto Bauer prolongé sur de nombreuses années ?", "¿Qué sacó Henryk Grossmann del esquema de reproducción de Otto Bauer prolongado durante muchos años?"], ["With a rising composition, the surplus value eventually becomes too small to finance accumulation: a tendency towards breakdown", "Avec une composition croissante, la plus-value finit par devenir trop petite pour financer l'accumulation : une tendance à l'effondrement", "Con una composición creciente, el plusvalor acaba siendo demasiado pequeño para financiar la acumulación: una tendencia al derrumbe"], [["That the scheme grows smoothly forever", "Que le schéma croît sans heurt pour toujours", "Que el esquema crece sin tropiezos para siempre"], ["That department II must disappear", "Que le secteur II doit disparaître", "Que el sector II debe desaparecer"], ["That wages rise without limit", "Que les salaires montent sans limite", "Que los salarios suben sin límite"]], ["Grossman (1929) used Bauer's own numbers against Bauer's harmonious conclusion; critics replied that the result depends on the assumed rates and that counteracting influences intervene.", "Grossmann (1929) a utilisé les chiffres mêmes de Bauer contre sa conclusion harmonieuse ; ses critiques ont répondu que le résultat dépend des taux supposés et que des causes contraires interviennent.", "Grossmann (1929) usó las propias cifras de Bauer contra su conclusión armoniosa; sus críticos respondieron que el resultado depende de las tasas supuestas y que intervienen causas contrarrestantes."]),
];

const profit: Q[] = [
  q("mx-pro-x01", ["What does Okishio's theorem (1961) claim?", "Qu'affirme le théorème d'Okishio (1961) ?", "¿Qué afirma el teorema de Okishio (1961)?"], ["A technique that lowers costs at current prices, adopted with real wages unchanged, cannot lower the general rate of profit", "Une technique qui réduit les coûts aux prix courants, adoptée à salaire réel inchangé, ne peut pas abaisser le taux général de profit", "Una técnica que reduce costes a precios corrientes, adoptada con salario real constante, no puede bajar la tasa general de ganancia"], [["The rate of profit always falls with new techniques", "Le taux de profit baisse toujours avec les nouvelles techniques", "La tasa de ganancia siempre baja con las técnicas nuevas"], ["Profits equal surplus value in every branch", "Les profits égalent la plus-value dans chaque branche", "Las ganancias igualan el plusvalor en cada rama"], ["Real wages must fall over time", "Les salaires réels doivent baisser avec le temps", "Los salarios reales deben bajar con el tiempo"]], ["Defenders of Marx's law answer that real wages rise, that fixed capital and its devaluation change the comparison, or (the temporal single-system interpretation) that the theorem's simultaneous valuation is the problem.", "Les défenseurs de la loi de Marx répondent que les salaires réels montent, que le capital fixe et sa dévalorisation changent la comparaison, ou (interprétation temporelle à système unique) que l'évaluation simultanée du théorème est en cause.", "Los defensores de la ley de Marx responden que los salarios reales suben, que el capital fijo y su desvalorización cambian la comparación, o (interpretación temporal de sistema único) que el problema es la valoración simultánea del teorema."]),
  q("mx-pro-x02", ["What did Bortkiewicz show about Marx's transformation of values into prices?", "Qu'a montré Bortkiewicz à propos de la transformation des valeurs en prix chez Marx ?", "¿Qué mostró Bortkiewicz sobre la transformación de valores en precios de Marx?"], ["Once inputs are also priced, total price equal to total value and total profit equal to total surplus value cannot both hold in general", "Une fois les intrants eux aussi exprimés en prix, prix total égal à valeur totale et profit total égal à plus-value totale ne peuvent pas tenir ensemble en général", "Una vez expresados también los insumos en precios, precio total igual a valor total y ganancia total igual a plusvalor total no pueden cumplirse juntos en general"], [["That prices always equal values", "Que les prix égalent toujours les valeurs", "Que los precios siempre igualan los valores"], ["That a general rate of profit cannot exist", "Qu'un taux général de profit ne peut exister", "Que no puede existir una tasa general de ganancia"], ["That Marx had made an arithmetic slip in his table", "Que Marx avait fait une erreur de calcul dans son tableau", "Que Marx había cometido un error aritmético en su tabla"]], ["His solution (1907) keeps one invariance and lets the other go; which one, and whether this matters, is the transformation debate summarised in Part 11 of the course.", "Sa solution (1907) garde un invariant et abandonne l'autre ; lequel, et si cela importe, c'est le débat sur la transformation résumé dans la partie 11 du cours.", "Su solución (1907) conserva un invariante y abandona el otro; cuál, y si importa, es el debate de la transformación resumido en la parte 11 del curso."]),
  q("mx-pro-x03", ["Why is the devaluation of capital both a symptom and a cure of crises in Volume III?", "Pourquoi la dévalorisation du capital est-elle à la fois symptôme et remède des crises au Livre III ?", "¿Por qué la desvalorización del capital es a la vez síntoma y remedio de las crisis en el Libro III?"], ["Over-accumulated capital cannot all be valorised; writing part of it down or destroying it restores the profit rate of what remains and opens a new expansion", "Le capital suraccumulé ne peut pas être entièrement valorisé ; en déprécier ou en détruire une part rétablit le taux de profit de ce qui reste et ouvre une nouvelle expansion", "El capital sobreacumulado no puede valorizarse entero; depreciar o destruir una parte restablece la tasa de ganancia de lo que queda y abre una nueva expansión"], [["Because devaluation raises wages", "Parce que la dévalorisation augmente les salaires", "Porque la desvalorización sube los salarios"], ["Because it increases the money supply", "Parce qu'elle augmente la masse monétaire", "Porque aumenta la masa monetaria"], ["It is neither: crises come only from outside", "Ni l'un ni l'autre : les crises viennent seulement de l'extérieur", "Ninguna de las dos: las crisis solo vienen de fuera"]], ["Chapter 15: crises are 'momentary and forcible solutions' of the contradictions of accumulation. Harvey's Madness of Economic Reason builds on this as 'devaluation'.", "Chapitre 15 : les crises sont des « solutions violentes et momentanées » des contradictions de l'accumulation. La Madness of Economic Reason de Harvey en fait la « dévalorisation ».", "Capítulo 15: las crisis son «soluciones momentáneas y violentas» de las contradicciones de la acumulación. La Madness of Economic Reason de Harvey lo desarrolla como «desvalorización»."]),
];

const credit: Q[] = [
  q("mx-cre-x01", ["Why is government debt the clearest case of fictitious capital for Marx?", "Pourquoi la dette publique est-elle pour Marx le cas le plus net de capital fictif ?", "¿Por qué la deuda pública es para Marx el caso más claro de capital ficticio?"], ["The money lent was spent long ago; the bond is only a claim on future taxes, capitalised as if a capital still existed", "L'argent prêté a été dépensé depuis longtemps ; l'obligation n'est qu'un droit sur des impôts futurs, capitalisé comme si un capital existait encore", "El dinero prestado se gastó hace tiempo; el bono es solo un derecho sobre impuestos futuros, capitalizado como si aún existiera un capital"], [["Because states never repay", "Parce que les États ne remboursent jamais", "Porque los Estados nunca pagan"], ["Because bonds bear no interest", "Parce que les obligations ne rapportent pas d'intérêt", "Porque los bonos no rinden interés"], ["Because the state produces surplus value", "Parce que l'État produit de la plus-value", "Porque el Estado produce plusvalor"]], ["Chapter 29: the bond's price moves with the interest rate and confidence, not with any productive capital. Shares are a less pure case, since a real capital stands behind them.", "Chapitre 29 : le prix de l'obligation suit le taux d'intérêt et la confiance, pas un capital productif. Les actions sont un cas moins pur, puisqu'un capital réel se trouve derrière elles.", "Capítulo 29: el precio del bono sigue al tipo de interés y a la confianza, no a un capital productivo. Las acciones son un caso menos puro, pues detrás hay un capital real."]),
  q("mx-cre-x02", ["Why does Marx tie absolute rent to the low organic composition of agriculture?", "Pourquoi Marx lie-t-il la rente absolue à la faible composition organique de l'agriculture ?", "¿Por qué Marx vincula la renta absoluta a la baja composición orgánica de la agricultura?"], ["With a low composition, agricultural value exceeds the price of production; landed property blocks the levelling of profit and keeps prices up, leaving room for rent even on the worst land", "Avec une composition faible, la valeur agricole dépasse le prix de production ; la propriété foncière empêche la péréquation du profit et maintient les prix, ce qui laisse place à une rente même sur la plus mauvaise terre", "Con una composición baja, el valor agrícola supera el precio de producción; la propiedad de la tierra impide la nivelación de la ganancia y mantiene los precios, lo que deja lugar a una renta incluso en la peor tierra"], [["Because farmers earn more than industrialists", "Parce que les fermiers gagnent plus que les industriels", "Porque los agricultores ganan más que los industriales"], ["Because land creates value by itself", "Parce que la terre crée de la valeur elle-même", "Porque la tierra crea valor por sí misma"], ["Because the worst land is the most fertile", "Parce que la plus mauvaise terre est la plus fertile", "Porque la peor tierra es la más fértil"]], ["Chapter 45. If farming catches up with industry in composition, the source Marx gives for absolute rent shrinks; later writers debate whether rent should be read as monopoly rent instead.", "Chapitre 45. Si l'agriculture rattrape l'industrie en composition, la source que Marx donne à la rente absolue se réduit ; des auteurs ultérieurs discutent s'il faut la lire plutôt comme une rente de monopole.", "Capítulo 45. Si la agricultura alcanza a la industria en composición, la fuente que Marx da a la renta absoluta se reduce; autores posteriores discuten si debe leerse más bien como renta de monopolio."]),
  q("mx-cre-x03", ["Why have the MEGA² editors and others criticised Engels's edition of Part 5 of Volume III?", "Pourquoi les éditeurs de la MEGA² et d'autres ont-ils critiqué l'édition par Engels de la cinquième section du Livre III ?", "¿Por qué los editores de la MEGA² y otros han criticado la edición de Engels de la quinta sección del Libro III?"], ["Marx's manuscript was a draft of notes and excerpts; Engels rearranged and supplemented it, giving it an order and finish it did not have", "Le manuscrit de Marx était un brouillon de notes et d'extraits ; Engels l'a réorganisé et complété, lui donnant un ordre et un fini qu'il n'avait pas", "El manuscrito de Marx era un borrador de notas y extractos; Engels lo reorganizó y completó, dándole un orden y un acabado que no tenía"], [["Engels left out Part 5 entirely", "Engels a entièrement omis la cinquième section", "Engels omitió por completo la quinta sección"], ["Engels translated it from French", "Engels l'a traduite du français", "Engels la tradujo del francés"], ["Engels changed Marx's conclusions on purpose", "Engels a changé exprès les conclusions de Marx", "Engels cambió a propósito las conclusiones de Marx"]], ["The 1864–65 manuscript, published in MEGA² II/4.2, lets readers see which chapter titles and transitions are Engels's. How much this changes the theory of credit is debated (Heinrich, Vollgraf).", "Le manuscrit de 1864-1865, publié dans la MEGA² II/4.2, permet de voir quels titres et transitions sont d'Engels. L'effet sur la théorie du crédit est discuté (Heinrich, Vollgraf).", "El manuscrito de 1864-1865, publicado en la MEGA² II/4.2, permite ver qué títulos y transiciones son de Engels. Cuánto cambia esto la teoría del crédito se discute (Heinrich, Vollgraf)."]),
];

